"""
benchmark_decomposer.py — Compare BenchmarkProfile vs FounderProfile.

Produces DimensionGap[] with exact deltas, priority ranks, and micro-queries.
Pure local computation. Zero LLM calls. Target <100ms.
"""

import math
from typing import Any, Optional

from .models import BenchmarkProfile, DimensionGap, FounderProfile, Milestone

DIMENSION_CONFIGS: list[tuple[str, float]] = [
    ("career_path", 2.0),
    ("deal_skills", 2.0),
    ("network_access", 1.5),
    ("founder_experience", 1.5),
    ("capital_requirements", 1.5),
    ("execution_distance", 2.0),
    ("base_rates", 1.5),
    ("leverage_type", 1.0),
    ("timing_windows", 0.8),
    ("failure_patterns", 1.0),
]

NETWORK_TIER: dict[str, float] = {"cold": 0, "warm": 3, "hot": 7, "insider": 10}

# Micro-query templates per dimension
QUERY_TEMPLATES: dict[str, list[str]] = {
    "career_path": [
        "What corporate roles did {benchmark_name} hold before {role}?",
        "Fastest path from {current_position} to {role} without {benchmark_name}'s background?",
        "How many career stops typical for {industry} fund director by age 25?",
        "Can someone skip investment banking and still reach VC director?",
        "What credentials gatekeep entry into {industry} in Vietnam?",
        "Typical years from analyst to director in {industry}?",
        "What internships led to {benchmark_name}'s first investment role?",
    ],
    "deal_skills": [
        "What deal sizes did {benchmark_name} close before age 25?",
        "Minimum deal count to become fund director in {industry}?",
        "What deal sizes are typical for first-time {role} in {industry}?",
        "Minimum track record to manage a {metric} fund?",
        "How to build deal track record with zero capital?",
        "What sourcing methods do junior VCs use to find deals?",
        "Entry-level deal roles in {industry} Vietnam accessible from outside?",
        "How long from first deal to leading a $40M+ transaction?",
    ],
    "network_access": [
        "Who are the top LP networks for Vietnam-focused funds?",
        "How to get warm introductions to {industry} GPs in Vietnam?",
        "What conferences do {benchmark_name}-tier professionals attend in {industry}?",
        "Alumni networks that feed into Vietnam {industry} roles?",
        "How did {benchmark_name} build their network so fast?",
        "Cold outreach conversion rate to senior {industry} professionals?",
        "Which LinkedIn communities are active for Vietnam {industry}?",
    ],
    "founder_experience": [
        "What revenue had {benchmark_name} generated by age {benchmark_age}?",
        "Typical entrepreneurship track record for {industry} analysts?",
        "Do VCs value founder experience when hiring analysts?",
        "How much business experience is needed to join {role}?",
        "Examples of founders who became fund managers in Vietnam?",
        "Does MMO/digital marketing background translate to {industry}?",
    ],
    "capital_requirements": [
        "What is minimum LP commit to access {benchmark_name}-tier funds?",
        "Can someone co-invest in Vietnam PE deals with under $50K?",
        "What GP commit % is typical for Vietnam VC/PE funds?",
        "Entry tickets for angel syndicates in Vietnam {industry}?",
        "Working capital needed to operate as deal scout in {industry}?",
        "Loan programs for {industry} deal participation in Vietnam?",
    ],
    "execution_distance": [
        "How many months to transition from tech/MMO to {industry} analyst?",
        "What certifications accelerate entry into {industry} roles?",
        "What is the fastest documented path from self-taught to {industry}?",
        "Skills gap between digital marketing and {industry} due diligence?",
        "Bootcamps or programs that place candidates into {industry}?",
        "What do {industry} firms look for that self-taught engineers can demonstrate?",
        "How did non-traditional hires enter {industry} in Southeast Asia?",
    ],
    "base_rates": [
        "What % of applicants get hired as {industry} analysts in Vietnam?",
        "How many people manage $450M+ funds in Vietnam under age 30?",
        "Success rate of career switchers entering {industry} after 25?",
        "What fraction of {industry} roles go to non-target university graduates?",
        "Base rate for reaching director-level in {industry} by age 28?",
        "Survival rate of {industry} funds in Vietnam in first 5 years?",
    ],
    "leverage_type": [
        "How does {benchmark_name} deploy capital as leverage vs sweat equity?",
        "Is code/media leverage recognized in {industry} hiring?",
        "What leverage types give fastest path to {industry} senior roles?",
        "Can content/audience substitute for capital access in {industry}?",
        "Examples of people using tech skills to enter {industry}?",
    ],
    "timing_windows": [
        "Is Vietnam {industry} currently in expansion or contraction phase?",
        "How many new funds launched in Vietnam in past 2 years?",
        "Regulatory changes in Vietnam affecting {industry} in 2025-2026?",
        "Window to enter {industry} before next fund cycle closes?",
        "Seasonal hiring patterns for {industry} analysts in Vietnam?",
    ],
    "failure_patterns": [
        "Most common failure mode for career switchers entering {industry}?",
        "Why do self-taught candidates get rejected from {industry} roles?",
        "What kills early {industry} career trajectories in Vietnam?",
        "Common mistakes by first-time deal analysts in {industry}?",
        "How many {industry} professionals burn out before director level?",
        "What due diligence errors end early {industry} careers?",
    ],
}


class BenchmarkDecomposer:
    """Compare benchmark vs founder → DimensionGap[] sorted by priority."""

    def decompose(
        self, benchmark: BenchmarkProfile, founder: FounderProfile
    ) -> list[DimensionGap]:
        b_data = self._extract_benchmark_data(benchmark)
        f_data = self._extract_founder_data(founder)

        gaps: list[DimensionGap] = []
        for dim_name, weight in DIMENSION_CONFIGS:
            b_val = b_data.get(dim_name)
            f_val = f_data.get(dim_name)
            gap_score = self._calc_gap(dim_name, b_val, f_val, benchmark, founder)
            gap_specific = self._describe_gap(dim_name, b_val, f_val, benchmark, founder)
            evidence = self._find_evidence(dim_name, benchmark)
            queries = self._generate_queries(dim_name, benchmark.name, benchmark)

            gaps.append(
                DimensionGap(
                    dimension=dim_name,
                    benchmark_value=b_val,
                    benchmark_evidence=evidence,
                    founder_value=f_val,
                    gap_score=gap_score,
                    gap_specific=gap_specific,
                    priority_rank=0,
                    micro_queries=queries,
                )
            )

        weight_map = {d: w for d, w in DIMENSION_CONFIGS}
        gaps.sort(
            key=lambda g: weight_map.get(g.dimension, 1.0) * g.gap_score,
            reverse=True,
        )
        for i, g in enumerate(gaps):
            g.priority_rank = i + 1

        return gaps

    # ── extraction helpers ────────────────────────────────────────────────────

    def _extract_benchmark_data(self, b: BenchmarkProfile) -> dict[str, Any]:
        career_stops = b.dimensions.get("career_path", {}).get("stops", 0)
        if not career_stops:
            career_stops = len(
                [m for m in b.milestones if m.category in ("career", "education")]
            )

        deal_total = b.dimensions.get("deal_skills", {}).get("total_value", 0.0)
        if not deal_total:
            deal_total = sum(
                m.quantified_value or 0
                for m in b.milestones
                if m.category == "deal"
            )

        deal_count = len([m for m in b.milestones if m.category == "deal"])
        fund_milestone = next(
            (m for m in b.milestones if m.quantified_value and m.quantified_value >= 100_000_000),
            None,
        )
        fund_size = fund_milestone.quantified_value if fund_milestone else 0.0

        ages = [m.age for m in b.milestones if m.age]
        min_age = min(ages) if ages else None
        max_age = max(ages) if ages else None

        bench_network = "insider"  # directors of $450M funds = insider tier

        return {
            "career_path": career_stops,
            "deal_skills": deal_total,
            "deal_count": deal_count,
            "network_access": bench_network,
            "founder_experience": (max_age or 0) - (min_age or 18) if max_age else 7,
            "capital_requirements": fund_size or deal_total,
            "execution_distance": max_age or 25,
            "base_rates": 0.01,  # ~1% reach director-level at 25
            "leverage_type": "capital",
            "timing_windows": "expansion",
            "failure_patterns": "low",  # survived = successful
        }

    def _extract_founder_data(self, f: FounderProfile) -> dict[str, Any]:
        total_exp = sum(f.experience_years.values())
        return {
            "career_path": max(1, len([v for v in f.experience_years.values() if v > 0])),
            "deal_skills": 0.0 if f.deals_closed == 0 else f.current_revenue_usd * 12,
            "deal_count": f.deals_closed,
            "network_access": f.network_quality,
            "founder_experience": total_exp,
            "capital_requirements": f.capital_usd,
            "execution_distance": f.age,
            "base_rates": 0.01,
            "leverage_type": "code" if "python" in f.skills else "media",
            "timing_windows": "expansion",
            "failure_patterns": "high" if f.deals_closed == 0 else "moderate",
        }

    # ── gap calculations ──────────────────────────────────────────────────────

    def _calc_gap(
        self,
        dim: str,
        b_val: Any,
        f_val: Any,
        benchmark: BenchmarkProfile,
        founder: FounderProfile,
    ) -> float:
        if dim == "career_path":
            b_stops = b_val if isinstance(b_val, (int, float)) else 4
            f_stops = f_val if isinstance(f_val, (int, float)) else 1
            if f_stops >= b_stops:
                return 0.0
            return min(10.0, (b_stops - f_stops) * 2.25)

        if dim == "deal_skills":
            if founder.deals_closed == 0:
                return 9.8
            b_deal = b_val if isinstance(b_val, (int, float)) and b_val > 0 else 551_000_000
            f_deal = f_val if isinstance(f_val, (int, float)) and f_val > 0 else 1
            if f_deal >= b_deal:
                return 0.0
            return min(10.0, math.log10(b_deal / f_deal) * 3)

        if dim == "network_access":
            b_tier = NETWORK_TIER.get(b_val, 10) if isinstance(b_val, str) else 10
            f_tier = NETWORK_TIER.get(f_val, 3) if isinstance(f_val, str) else 3
            if f_tier >= b_tier:
                return 0.0
            return min(10.0, float(b_tier - f_tier))

        if dim == "capital_requirements":
            b_cap = b_val if isinstance(b_val, (int, float)) and b_val > 0 else 450_000_000
            f_cap = f_val if isinstance(f_val, (int, float)) and f_val > 0 else 1
            if f_cap >= b_cap:
                return 0.0
            return min(10.0, math.log10(b_cap / f_cap) * 1.8)

        if dim == "execution_distance":
            b_age = b_val if isinstance(b_val, (int, float)) else 25
            f_age = f_val if isinstance(f_val, (int, float)) else founder.age
            exp_gap = max(0, b_age - f_age + 3)  # +3 for experience context
            return min(10.0, exp_gap * 0.8)

        if dim == "founder_experience":
            b_exp = b_val if isinstance(b_val, (int, float)) else 7
            f_exp = f_val if isinstance(f_val, (int, float)) else 3
            if f_exp >= b_exp:
                return 0.0
            return min(10.0, (b_exp - f_exp) * 1.2)

        if dim == "base_rates":
            return 6.0  # static: base rates are always a moderate gap

        if dim == "leverage_type":
            b_lev = b_val if isinstance(b_val, str) else "capital"
            f_lev = f_val if isinstance(f_val, str) else "code"
            return 0.0 if b_lev == f_lev else 5.0

        if dim == "timing_windows":
            return 2.5  # low static gap — timing is situational

        if dim == "failure_patterns":
            f_fail = f_val if isinstance(f_val, str) else "high"
            score_map = {"low": 2.0, "moderate": 4.5, "high": 6.0}
            return score_map.get(f_fail, 5.0)

        return 5.0

    # ── description helpers ───────────────────────────────────────────────────

    def _describe_gap(
        self,
        dim: str,
        b_val: Any,
        f_val: Any,
        benchmark: BenchmarkProfile,
        founder: FounderProfile,
    ) -> str:
        name = benchmark.name.split()[-1]  # last name for brevity

        if dim == "career_path":
            return (
                f"{name} had {b_val} career stops (IB, VC analyst, VP, director); "
                f"founder has {f_val} distinct roles — gap of {(b_val or 4) - (f_val or 1)} stops"
            )
        if dim == "deal_skills":
            if founder.deals_closed == 0:
                return (
                    f"{name} led $551M+ in deals by age 25; founder has 0 closed deals — "
                    "critical credibility gap"
                )
            return (
                f"{name} deal volume: ~${b_val:,.0f}; founder: ~${f_val:,.0f} — "
                f"{math.log10((b_val or 1) / max(f_val or 1, 1)):.1f} orders of magnitude"
            )
        if dim == "network_access":
            return (
                f"{name} has insider-tier network (GPs, LPs, founders); "
                f"founder at {f_val}-tier — {NETWORK_TIER.get('insider', 10) - NETWORK_TIER.get(f_val or 'warm', 3):.0f} tiers below"
            )
        if dim == "capital_requirements":
            return (
                f"{name} managed ${(b_val or 450_000_000):,.0f}; founder capital: "
                f"${(f_val or founder.capital_usd):,.0f} — "
                f"{math.log10((b_val or 450_000_000) / max(f_val or founder.capital_usd, 1)):.1f} orders of magnitude short"
            )
        if dim == "execution_distance":
            gap_yrs = max(0, (b_val or 25) - founder.age + 3)
            return (
                f"{name} reached director at ~25; founder age {founder.age} — "
                f"~{gap_yrs} years of compressed steps needed"
            )
        if dim == "founder_experience":
            return (
                f"{name} had {b_val}+ yrs active career experience; "
                f"founder has {f_val} yrs total (0 in corporate finance)"
            )
        if dim == "base_rates":
            return (
                "~1% of Vietnam finance professionals reach director-level by 25; "
                "founder path diverges significantly from benchmark sample"
            )
        if dim == "leverage_type":
            return (
                f"{name} leverages capital ($450M AUM); "
                f"founder leverages {f_val} — different leverage class, conversion needed"
            )
        if dim == "timing_windows":
            return (
                "Vietnam VC market expansion phase active; timing neutral — "
                "window open but not uniquely advantageous for late entrant"
            )
        if dim == "failure_patterns":
            return (
                f"Founder risk profile: {f_val} (0 deals closed, self-taught, no {dim.replace('_', ' ')} mitigation track record)"
            )
        return f"Gap in {dim}: benchmark={b_val}, founder={f_val}"

    def _find_evidence(self, dim: str, benchmark: BenchmarkProfile) -> str:
        category_map = {
            "career_path": ("career", "education"),
            "deal_skills": ("deal",),
            "capital_requirements": ("deal",),
            "founder_experience": ("business",),
            "execution_distance": ("career",),
        }
        cats = category_map.get(dim, ())
        relevant = [m for m in benchmark.milestones if m.category in cats]
        if relevant:
            m = relevant[0]
            return (
                f"age {m.age}: {m.achievement}"
                + (f" (${m.quantified_value:,.0f})" if m.quantified_value else "")
            )
        return benchmark.dimensions.get(dim, {}).get("evidence", f"Inferred from {benchmark.name} profile")

    def _generate_queries(
        self, dim: str, benchmark_name: str, benchmark: BenchmarkProfile
    ) -> list[str]:
        templates = QUERY_TEMPLATES.get(dim, [])
        fund_ms = next(
            (m for m in benchmark.milestones if m.quantified_value and m.quantified_value >= 100_000_000),
            None,
        )
        replacements = {
            "{benchmark_name}": benchmark_name,
            "{role}": "fund director",
            "{industry}": "venture capital / private equity",
            "{current_position}": "self-taught developer",
            "{market}": "Vietnam",
            "{metric}": f"${(fund_ms.quantified_value / 1e6):.0f}M" if fund_ms else "$450M",
            "{benchmark_age}": str(
                next((m.age for m in benchmark.milestones if m.quantified_value), 25)
            ),
        }
        queries = []
        for tmpl in templates:
            q = tmpl
            for k, v in replacements.items():
                q = q.replace(k, v)
            queries.append(q)
        return queries
